#!/usr/bin/env bash
# Writes the 2 missing frontend files: LangContext.jsx + strings.js (complete)
set -euo pipefail
if [ ! -d src ]; then echo "ERROR: run from ~/Documents/AgroMart/frontend"; exit 1; fi
mkdir -p src/context src/i18n
echo '' | base64 -d > 'src/context/LangContext.jsx' && echo '  wrote src/context/LangContext.jsx'
echo '' | base64 -d > 'src/i18n/strings.js' && echo '  wrote src/i18n/strings.js'
echo ""; echo "Done. Now run: npm run dev"
